<script setup lang="ts">
import { onMounted, ref } from 'vue'; import AppState from '../../components/AppState.vue'; import UiButton from '../../components/UiButton.vue'; import UiField from '../../components/UiField.vue'; import { api } from '../../lib/api'
const libraries=ref<any[]>([]);const loading=ref(true);const error=ref('');const name=ref('');const libraryPath=ref('');const rescanIntervalMinutes=ref(0);const busy=ref<number|null>(null);const notice=ref('')
async function load(){loading.value=true;try{libraries.value=(await api<{libraries:any[]}>('/api/v1/admin/libraries')).libraries;error.value=''}catch(e){error.value=e instanceof Error?e.message:'Falha ao carregar.'}finally{loading.value=false}}
async function create(){error.value='';try{await api('/api/v1/admin/libraries',{method:'POST',body:JSON.stringify({name:name.value,path:libraryPath.value,rescanIntervalMinutes:rescanIntervalMinutes.value})});name.value='';libraryPath.value='';rescanIntervalMinutes.value=0;notice.value='Biblioteca adicionada.';await load()}catch(e){error.value=e instanceof Error?e.message:'Falha ao adicionar.'}}
async function scan(id:number){busy.value=id;notice.value='';try{const result=await api<{job:any}>(`/api/v1/admin/libraries/${id}/scan?async=true`,{method:'POST'});notice.value=`Scan #${result.job.id} entrou na fila. Acompanhe em Jobs.`;await load()}catch(e){error.value=e instanceof Error?e.message:'Falha no scan.'}finally{busy.value=null}}onMounted(load)
</script>
<template><div><header class="page-header"><p class="eyebrow">Fontes do acervo</p><h1>Bibliotecas</h1><p>Cadastre somente caminhos montados dentro das roots permitidas pelo servidor.</p></header><p v-if="notice" class="alert alert--success" role="status">{{ notice }}</p><p v-if="error" class="alert alert--error" role="alert">{{ error }}</p><section class="settings-section"><h2>Adicionar biblioteca</h2><form class="form-row form-row--library" @submit.prevent="create"><UiField label="Nome" for-id="library-name"><input id="library-name" v-model="name" required placeholder="Acervo principal" /></UiField><UiField label="Caminho no servidor" for-id="library-path" hint="Exemplo: /books"><input id="library-path" v-model="libraryPath" required placeholder="/books" /></UiField><UiField label="Reescaneamento automático" for-id="library-rescan"><select id="library-rescan" v-model.number="rescanIntervalMinutes"><option :value="0">Somente manual</option><option :value="15">A cada 15 minutos</option><option :value="60">A cada hora</option><option :value="360">A cada 6 horas</option><option :value="1440">Diariamente</option><option :value="10080">Semanalmente</option></select></UiField><UiButton type="submit" variant="primary">Adicionar biblioteca</UiButton></form></section><AppState v-if="loading" kind="loading" /><section v-else class="admin-list" aria-label="Bibliotecas cadastradas"><article v-for="library in libraries" :key="library.id"><div><h2><RouterLink :to="`/admin/libraries/${library.id}`">{{ library.name }}</RouterLink></h2><code>{{ library.path }}</code><p>{{ library.bookCount }} livros · {{ library.errorCount || 0 }} erros · {{ library.rescanIntervalMinutes ? `Auto scan a cada ${library.rescanIntervalMinutes} min` : 'Scan manual' }}<span v-if="library.last_scan_at"> · Último scan {{ new Date(library.last_scan_at+'Z').toLocaleString() }}</span></p></div><div class="reader-actions"><RouterLink class="button button--secondary" :to="`/admin/libraries/${library.id}`">Abrir</RouterLink><UiButton :disabled="busy===library.id" @click="scan(library.id)">{{ busy===library.id?'Enfileirando…':'Escanear agora' }}</UiButton></div></article><AppState v-if="!libraries.length" kind="empty" title="Nenhuma biblioteca cadastrada" message="Adicione a pasta montada onde seus EPUBs e PDFs estão guardados." /></section></div></template>
